import os
import sys
import subprocess
import platform

def display_help():
    help_text = """
    Usage:
        python uninstall_adware.py --uninstall <software_name>

    Arguments:
        --uninstall <software_name> : Specify the name of the software to uninstall.
        --help                      : Display this help message.
    """
    print(help_text)

def is_valid_software_name(name):
    # Basic validation to avoid harmful commands
    return name.isalnum()

def stop_service(service_name):
    try:
        if platform.system() == "Windows":
            subprocess.run(["sc", "stop", service_name], check=True)
        elif platform.system() == "Linux":
            subprocess.run(["systemctl", "stop", service_name], check=True)
        print(f"Service '{service_name}' stopped successfully.")
    except subprocess.CalledProcessError:
        print(f"Failed to stop the service '{service_name}'. It may not exist or require elevated permissions.")

def uninstall_software(software_name):
    try:
        if platform.system() == "Windows":
            # Uninstall via Windows command
            subprocess.run(["wmic", "product", "where", f"name='{software_name}'", "call", "uninstall"], check=True)
        elif platform.system() == "Linux":
            # Uninstall via package manager
            subprocess.run(["sudo", "apt-get", "remove", "--purge", "-y", software_name], check=True)
        print(f"Software '{software_name}' uninstalled successfully.")
    except subprocess.CalledProcessError:
        print(f"Failed to uninstall '{software_name}'. Ensure it exists and try again.")
    except Exception as e:
        print(f"Unexpected error: {e}")

def main():
    if len(sys.argv) < 2 or "--help" in sys.argv:
        display_help()
        sys.exit(0)

    if "--uninstall" in sys.argv:
        index = sys.argv.index("--uninstall")
        if index + 1 < len(sys.argv):
            software_name = sys.argv[index + 1]
            if is_valid_software_name(software_name):
                print(f"Preparing to uninstall '{software_name}'...")
                stop_service(software_name)
                uninstall_software(software_name)
            else:
                print("Error: Invalid software name. Only alphanumeric names are allowed.")
        else:
            print("Error: No software name provided for uninstallation.")
    else:
        print("Error: Invalid arguments. Use '--help' for usage information.")

if __name__ == "__main__":
    main()

