            logging.info(f"Command output: {result.stdout}")
        else:
            logging.error(f"Command failed with error: {result.stderr}")
    except subprocess.TimeoutExpired:
        logging.error(f"Command '{command}' timed out after {timeout} seconds")
    except Exception as e:
        logging.error(f"Unexpected error while executing command: {e}")

def bounded_loop_task(task_name: str, iterations: int, manipulation_func=None):
    """
    Execute a bounded loop for a specific task, optionally manipulating data.
    """
    logging.info(f"Starting task '{task_name}' with {iterations} iterations")
    for i in range(iterations):
        logging.info(f"Iteration {i + 1}/{iterations} for task '{task_name}'")
        data = f"Data from iteration {i + 1}"
        if manipulation_func:
            data = manipulation_func(data)
        logging.info(f"Processed data: {data}")
        time.sleep(1)  # Simulate work being done

