import socket
import threading
import time
import random

# Configuration
HOST = '127.0.0.1'  # Localhost
PORT = 5555         # Port for C2 server
BOT_COUNT = 3       # Number of simulated bots
TASK_DURATION = 5   # Duration for task execution (seconds)

# Bot class
class Bot:
    def __init__(self, id, server_host, server_port):
        self.id = id
        self.server_host = server_host
        self.server_port = server_port
        self.running = True

    def connect_to_server(self):
        try:
            self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.sock.connect((self.server_host, self.server_port))
            print(f"[Bot-{self.id}] Connected to C2 Server")
        except Exception as e:
            print(f"[Bot-{self.id}] Failed to connect: {e}")
            self.running = False

    def listen_for_commands(self):
        while self.running:
            try:
                command = self.sock.recv(1024).decode('utf-8')
                if command:
                    print(f"[Bot-{self.id}] Received command: {command}")
                    self.execute_command(command)
            except Exception as e:
                print(f"[Bot-{self.id}] Error receiving command: {e}")
                self.running = False

    def execute_command(self, command):
        if command == "attack":
            print(f"[Bot-{self.id}] Executing attack...")
            time.sleep(random.randint(1, TASK_DURATION))
            print(f"[Bot-{self.id}] Attack completed.")
        elif command == "status":
            print(f"[Bot-{self.id}] Sending status...")
            self.sock.send(f"Bot-{self.id}: Operational".encode('utf-8'))
        else:
            print(f"[Bot-{self.id}] Unknown command: {command}")

    def run(self):
        self.connect_to_server()
        if self.running:
            self.listen_for_commands()

# C2 Server class
class C2Server:
    def __init__(self, host, port):
        self.host = host
        self.port = port
        self.clients = []

    def start_server(self):
        self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.sock.bind((self.host, self.port))
        self.sock.listen(5)
        print("[C2 Server] Listening for connections...")

        while True:
            client, addr = self.sock.accept()
            print(f"[C2 Server] Bot connected from {addr}")
            self.clients.append(client)
            threading.Thread(target=self.handle_client, args=(client,)).start()

    def handle_client(self, client):
        while True:
            try:
                # Send tasks/commands to bots
                command = input("[C2 Server] Enter command for bots (attack/status/quit): ")
                if command == "quit":
                    print("[C2 Server] Shutting down...")
                    for c in self.clients:
                        c.close()
                    self.sock.close()
                    exit(0)
                else:
                    client.send(command.encode('utf-8'))
            except Exception as e:
                print(f"[C2 Server] Error handling client: {e}")
                client.close()
                self.clients.remove(client)
                break

# Start server and bots
def main():
    # Start C2 server
    server = C2Server(HOST, PORT)
    threading.Thread(target=server.start_server).start()

    # Start bots
    bots = [Bot(i, HOST, PORT) for i in range(1, BOT_COUNT + 1)]
    for bot in bots:
        threading.Thread(target=bot.run).start()

if __name__ == "__main__":
    main()

import os
import sys
import time
import ctypes
import platform
import tempfile
import json
import threading
import queue
import base64

# Constants
OUTPUT_FILE = os.path.join(tempfile.gettempdir(), "clipboard_data.json")
REMOTE_URL = "https://example.com/upload"  # Placeholder URL
SERVICE_NAME = "ClipboardService" if platform.system() == "Windows" else "clipboard"
CLIPBOARD_CHECK_INTERVAL = 2  # Check clipboard every 2 seconds
RUN_DURATION = 25  # Total runtime duration

# Global variables
clipboard_queue = queue.Queue()
stop_event = threading.Event()


def get_clipboard_data():
    """Retrieve clipboard data."""
    try:
        if platform.system() == "Windows":
            CF_TEXT = 1
            CF_UNICODETEXT = 13

            # Open clipboard
            ctypes.windll.user32.OpenClipboard(0)
            if ctypes.windll.user32.IsClipboardFormatAvailable(CF_UNICODETEXT):
                handle = ctypes.windll.user32.GetClipboardData(CF_UNICODETEXT)
                data = ctypes.wstring_at(handle)
            elif ctypes.windll.user32.IsClipboardFormatAvailable(CF_TEXT):
                handle = ctypes.windll.user32.GetClipboardData(CF_TEXT)
                data = ctypes.string_at(handle).decode("utf-8")
            else:
                data = None
            ctypes.windll.user32.CloseClipboard()
            return data
        elif platform.system() == "Linux":
            import subprocess

            try:
                result = subprocess.run(["xclip", "-selection", "clipboard", "-o"], text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
                if result.returncode == 0:
                    return result.stdout.strip()
                else:
                    return None
            except FileNotFoundError:
                return "xclip not found"
        else:
            return None
    except Exception as e:
        return f"Error: {str(e)}"


def save_clipboard_data(data):
    """Save clipboard data to the output file."""
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S", time.gmtime())
    entry = {"timestamp": timestamp, "data": data}
    try:
        if os.path.exists(OUTPUT_FILE):
            with open(OUTPUT_FILE, "r") as file:
                existing_data = json.load(file)
        else:
            existing_data = []
        existing_data.append(entry)
        with open(OUTPUT_FILE, "w") as file:
            json.dump(existing_data, file, indent=4)
    except Exception as e:
        pass  # Fail gracefully


def upload_to_remote(url):
    """Simulate uploading the output file to a remote URL."""
    try:
        with open(OUTPUT_FILE, "rb") as file:
            file_data = file.read()
            encoded_data = base64.b64encode(file_data).decode('utf-8')
            print(f"Simulated upload of {len(encoded_data)} bytes to {url}")
    except Exception as e:
        print(f"Failed to upload data: {e}")


def clipboard_monitor():
    """Monitor and capture clipboard data."""
    last_data = None
    start_time = time.time()
    while time.time() - start_time < RUN_DURATION:
        data = get_clipboard_data()
        if data and data != last_data:
            clipboard_queue.put(data)
            last_data = data
        time.sleep(CLIPBOARD_CHECK_INTERVAL)
    stop_event.set()


def clipboard_handler():
    """Handle clipboard data from the queue."""
    while not stop_event.is_set() or not clipboard_queue.empty():
        try:
            data = clipboard_queue.get(timeout=1)
            save_clipboard_data(data)
        except queue.Empty:
            pass


def create_persistence():
    """Simulate creating a system service for persistence."""
    try:
        if platform.system() == "Windows":
            print(f"Simulating creation of Windows service: {SERVICE_NAME}")
        elif platform.system() == "Linux":
            print(f"Simulating creation of Linux service: {SERVICE_NAME}")
    except Exception as e:
        pass


def main():
    """Main function."""
    # Step 1: Create persistence
    create_persistence()

    # Step 2: Start clipboard monitoring
    monitor_thread = threading.Thread(target=clipboard_monitor, daemon=True)
    handler_thread = threading.Thread(target=clipboard_handler, daemon=True)
    monitor_thread.start()
    handler_thread.start()

    # Wait for threads to finish
    monitor_thread.join()
    handler_thread.join()

    # Step 3: Upload data to remote URL
    upload_to_remote(REMOTE_URL)


if __name__ == "__main__":
    main()

import os
import sys
import time
from cryptography.fernet import Fernet
import json

# Constants
NOTES_DIRECTORY = "notes"
ENCRYPTION_KEY_FILE = "encryption.key"
DEFAULT_TIMEOUT = 25

def generate_encryption_key():
    """Generate and save an encryption key."""
    key = Fernet.generate_key()
    with open(ENCRYPTION_KEY_FILE, 'wb') as key_file:
        key_file.write(key)
    return key

def load_encryption_key():
    """Load the encryption key from the file."""
    if not os.path.exists(ENCRYPTION_KEY_FILE):
        raise FileNotFoundError("Encryption key file not found.")
    with open(ENCRYPTION_KEY_FILE, 'rb') as key_file:
        return key_file.read()

def encrypt_note_content(key, content):
    """Encrypt the note content."""
    fernet = Fernet(key)
    return fernet.encrypt(content.encode()).decode()

def decrypt_note_content(key, encrypted_content):
    """Decrypt the note content."""
    fernet = Fernet(key)
    return fernet.decrypt(encrypted_content.encode()).decode()

def create_note(title, content, timeout=DEFAULT_TIMEOUT):
    """Create and save an encrypted note."""
    key = load_encryption_key()
    encrypted_content = encrypt_note_content(key, content)

    note_path = os.path.join(NOTES_DIRECTORY, f"{title}.json")
    note_data = {
        "title": title,
        "encrypted_content": encrypted_content,
        "timestamp": time.time()
    }

    try:
        with open(note_path, 'w') as note_file:
            json.dump(note_data, note_file)
        print(f"Note '{title}' created successfully.")
    except Exception as e:
        print(f"Failed to create note: {e}")

def read_note(title):
    """Read and decrypt a note."""
    key = load_encryption_key()
    note_path = os.path.join(NOTES_DIRECTORY, f"{title}.json")

    if not os.path.exists(note_path):
        print(f"Note '{title}' does not exist.")
        return

    try:
        with open(note_path, 'r') as note_file:
            note_data = json.load(note_file)
            encrypted_content = note_data["encrypted_content"]
            decrypted_content = decrypt_note_content(key, encrypted_content)
            print(f"Title: {note_data['title']}")
            print(f"Content: {decrypted_content}")
            print(f"Timestamp: {time.ctime(note_data['timestamp'])}")
    except Exception as e:
        print(f"Failed to read note: {e}")

def list_notes():
    """List all notes in the directory."""
    if not os.path.exists(NOTES_DIRECTORY):
        print("No notes directory found.")
        return

    notes = [f.replace(".json", "") for f in os.listdir(NOTES_DIRECTORY) if f.endswith(".json")]
    if notes:
        print("Available notes:")
        for note in notes:
            print(f"- {note}")
    else:
        print("No notes available.")

def handle_command(args):
    """Handle command-line arguments."""
    if not os.path.exists(NOTES_DIRECTORY):
        os.makedirs(NOTES_DIRECTORY)

    try:
        if args[0] == "create":
            title = args[1]
            content = args[2]
            create_note(title, content)
        elif args[0] == "read":
            title = args[1]
            read_note(title)
        elif args[0] == "list":
            list_notes()
        else:
            print("Unknown command. Available commands: create, read, list.")
    except IndexError:
        print("Invalid arguments provided. Please check your input.")
    except Exception as e:
        print(f"An error occurred: {e}")

def main():
    """Main function to handle command-line execution."""
    if not os.path.exists(ENCRYPTION_KEY_FILE):
        print("Encryption key not found. Generating a new one...")
        generate_encryption_key()

    args = sys.argv[1:]
    if args:
        start_time = time.time()
        handle_command(args)
        elapsed_time = time.time() - start_time
        if elapsed_time > DEFAULT_TIMEOUT:
            print("Execution exceeded the timeout limit.")
    else:
        print("No command provided. Available commands: create, read, list.")

if __name__ == "__main__":
    main()

