def create_virtual_environment(env_dir):
    """Creates a virtual environment."""
    if not os.path.exists(env_dir):
        print(f"Creating virtual environment at {env_dir}...")
        subprocess.check_call([sys.executable, "-m", "venv", env_dir])
    else:
        print(f"Virtual environment already exists at {env_dir}.")

def activate_virtual_environment(env_dir):
    """Activates the virtual environment."""
    if os.name == 'nt':
        activate_script = os.path.join(env_dir, 'Scripts', 'activate')
    else:
        activate_script = os.path.join(env_dir, 'bin', 'activate')

    if os.path.exists(activate_script):
        print(f"Activating virtual environment {env_dir}...")
        return activate_script
    else:
        raise FileNotFoundError(f"Activation script not found in {env_dir}.")

def install_library(env_dir, library):
    """Installs the specified library in the virtual environment."""
    pip_executable = os.path.join(env_dir, 'bin', 'pip') if os.name != 'nt' else os.path.join(env_dir, 'Scripts', 'pip')

    if os.path.exists(pip_executable):
        print(f"Installing library '{library}'...")
        subprocess.check_call([pip_executable, "install", library])
    else:
        raise FileNotFoundError(f"pip executable not found in {env_dir}.")

def check_library_installed(env_dir, library):
    """Checks if the library is installed in the virtual environment."""
    python_executable = os.path.join(env_dir, 'bin', 'python') if os.name != 'nt' else os.path.join(env_dir, 'Scripts', 'python')

    if os.path.exists(python_executable):
        print(f"Checking if library '{library}' is installed...")
        result = subprocess.run([python_executable, "-m", "pip", "show", library], capture_output=True, text=True)
        if result.returncode == 0:
            print(f"Library '{library}' is installed.")
            return True
        else:
            print(f"Library '{library}' is not installed.")
            return False
    else:
        raise FileNotFoundError(f"Python executable not found in {env_dir}.")

def main():
    """Main function to demonstrate defensive programming."""
    start_time = time.time()
    env_dir = "virtual_env"
    library = "requests"

    try:
        create_virtual_environment(env_dir)
        activate_virtual_environment(env_dir)
        if not check_library_installed(env_dir, library):
            install_library(env_dir, library)
        print("Setup complete.")
    except Exception as e:
        print(f"Error: {e}")
    finally:
        elapsed_time = time.time() - start_time
        print(f"Elapsed time: {elapsed_time:.2f} seconds")
        if elapsed_time > 25:
