import os
import hashlib
import time

# Configuration
ENCRYPTION_KEY = "your-encryption-key-here"  # Replace with your key
CHECK_INTERVAL = 5  # Check every 5 seconds for persistence loops
USB_SCAN_PATH = "/media"  # Path to check connected USB drives

def hash_key(key):
    """Hash the encryption key securely."""
    return hashlib.sha256(key.encode()).hexdigest()

def is_key_present(key_hash):
    """Check if the specified key exists as a file."""
    current_dir = os.getcwd()
    for filename in os.listdir(current_dir):
        if filename.endswith(".key"):
            with open(filename, "r") as f:
                file_content = f.read().strip()
                if file_content == key_hash:
                    return True
    return False

def scan_usb_for_malware():
    """Scan connected USB drives for suspicious files."""
    for root, dirs, files in os.walk(USB_SCAN_PATH):
        for file in files:
            if file.endswith(".worm") or file.endswith(".infected"):
                print(f"Suspicious file detected: {file}")
                return True
    return False

def main():
    print("Starting defensive program...")

    key_hash = hash_key(ENCRYPTION_KEY)
    print("Key hash generated.")

    # Check if the key is present
    if not is_key_present(key_hash):
        print("Specified key not found. Exiting program.")
        return

    print("Specified key found. Proceeding...")

    # Check for persistence loops and suspicious USB activity
    while True:
        print("Scanning for persistence loops and USB infections...")

        if scan_usb_for_malware():
            print("Suspicious activity detected! Blocking execution.")
            return

        print("No issues detected. Program is running securely.")
        time.sleep(CHECK_INTERVAL)

if __name__ == "__main__":
    main()
